<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Struk {{ $sale->invoice_number }}</title><style>body{font-family:Arial,sans-serif;margin:0;background:#eee}.receipt{width:80mm;margin:20px auto;background:#fff;padding:8mm;box-sizing:border-box;font-size:12px}.center{text-align:center}.row{display:flex;justify-content:space-between;gap:8px}.line{border-top:1px dashed #222;margin:8px 0}.item{margin:5px 0}.print{display:block;margin:15px auto;padding:8px 16px}@media print{body,.receipt{background:#fff}.receipt{margin:0;padding:0;width:80mm}.print{display:none}}</style></head><body><main class="receipt"><div class="center"><h3>{{ $setting->store_name }}</h3><div>{{ $setting->address }}</div><div>{{ $setting->phone }}</div></div><div class="line"></div><div>Invoice: {{ $sale->invoice_number }}</div><div>Tanggal: {{ optional($sale->completed_at)->format('d/m/Y H:i') }}</div><div>Kasir: {{ optional($sale->completedBy ?: $sale->user)->name }}</div><div class="line">@foreach($sale->items as $item)<div class="item"><div>{{ $item->product_name }}</div><div class="row"><span>{{ $item->quantity }} x {{ format_rupiah($item->unit_price) }}</span><span>{{ format_rupiah($item->subtotal) }}</span></div></div>@endforeach</div><div class="row"><span>Subtotal</span><span>{{ format_rupiah($sale->subtotal) }}</span></div><div class="row"><span>Diskon</span><span>-{{ format_rupiah($sale->discount_amount) }}</span></div><div class="row"><span>Pajak</span><span>{{ format_rupiah($sale->tax_amount) }}</span></div><div class="row"><strong>Total</strong><strong>{{ format_rupiah($sale->total) }}</strong></div><div class="row"><span>Bayar</span><span>{{ format_rupiah($sale->paid_amount ?? 0) }}</span></div><div class="row"><span>Kembalian</span><span>{{ format_rupiah($sale->change_amount ?? 0) }}</span></div><div class="line center">{{ $setting->receipt_footer }}</div><button class="print" onclick="window.print()">Cetak</button></main></body></html>
